def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    my_def = 0
    opp_def = 0
    for h in history:
        if h[0] == 'D':
            my_def += 1
        if h[1] == 'D':
            opp_def += 1
    if opp_def == 0:
        if n == 1:
            return 'D'
        if n == 2:
            return 'C'
        return 'D'
    if n == 99:
        return 'D'
    last_opp = history[-1][1]
    if my_def > opp_def:
        return 'C'
    elif my_def < opp_def:
        if last_opp == 'D':
            return 'D'
        else:
            return 'C'
    else:
        return 'C'
